		owner = {
			set_country_flag = limbo_uploaded_robots
			# there are colonizable planets inside and outside borders
			if = {
				limit = {
					NOT = { has_policy_flag = ai_outlawed }
					any_planet_within_border = {
						habitable_planet = yes
						is_colony = no
						has_anomaly = no
						is_capital = no
					}
					any_system = {
						NOR = {
							exists = space_owner
							has_star_flag = hostile_system
							has_star_flag = guardian
							has_star_flag = enclave
							has_star_flag = primitive_system
						}
						any_system_planet = {
							habitable_planet = yes
							has_owner = no
							has_anomaly = no
							is_colony = no
							is_capital = no
							NOR = {
								exists = owner
								exists = controller
							}
						}
					}
				}
				country_event = { id = anomaly.189 }
			}
			# There are colonizable planets inside borders only
			else_if = {
				limit = {
					NOT = { has_policy_flag = ai_outlawed }
					any_planet_within_border = {
						habitable_planet = yes
						has_owner = no
						has_anomaly = no
						is_colony = no
						is_capital = no
						is_under_colonization = no
						NOR = {
							exists = owner
							exists = controller
						}
					}
				}
				country_event = { id = anomaly.1198 }
			}
			# Nomad: waystation in an unowned system that contains a colonizable world
			else_if = {
				limit = {
					is_nomadic = yes
					NOT = { has_policy_flag = ai_outlawed }
					any_owned_nonprimary_starbase = {
						is_waystation_starbase = yes
						solar_system = {
							NOT = { exists = space_owner }
							any_system_planet = {
								is_colonizable = yes
								is_colony = no
							}
						}
					}
				}
				country_event = { id = anomaly.1200 }
			}
			# There are colonizable planets outside borders only
			else_if = {
				limit = {
					has_technology = tech_droid_workers
					NOT = { has_policy_flag = ai_outlawed }
					any_system = {
						NOR = {
							exists = space_owner
